import { useEffect, useState } from "react"
import { GoogleLogin, CredentialResponse } from "@react-oauth/google"

import { API_URL } from "../configs"
import { apiFetch, decodeProfile, GoogleProfile, refreshSessionIfDue, setToken, signOut, useAuthToken } from "../auth"
import AppleSignIn from "./AppleSignIn"
import { useTheme } from "../theme"
import "./SignIn.css"

// A signed-in caller defaults to the "guest" role in the API until an admin
// promotes them, so a fresh sign-in can still see 401/403s from protected
// routes - that's expected, not a bug in this component.
async function provisionUser(): Promise<void> {
    try {
        await apiFetch(`${API_URL}/users`, { method: "POST" })
    } catch (error) {
        console.error("Failed to provision user after sign-in", error)
    }
}

export default function SignIn() {
    const { dark } = useTheme()
    const token = useAuthToken()
    const [profile, setProfile] = useState<GoogleProfile | null>(null)
    const [confirmingDelete, setConfirmingDelete] = useState(false)
    const [deleting, setDeleting] = useState(false)

    useEffect(() => {
        setProfile(token ? decodeProfile(token) : null)

        // Google injects the One Tap picker directly into the page outside
        // React's control, so unmounting <GoogleLogin> here doesn't remove
        // it - a prompt that was already showing before sign-in completed
        // (e.g. a silent re-auth in another tab) would otherwise linger on
        // screen indefinitely.
        if (token) {
            ;(window as any).google?.accounts?.id?.cancel?.()
        }
    }, [token])

    // Someone signed in with Apple stays signed in by renewing the API's
    // session token as it nears its end
    useEffect(() => {
        void refreshSessionIfDue(API_URL)
    }, [])

    const handleDeleteAccount = async () => {
        setDeleting(true)
        try {
            const response = await apiFetch(`${API_URL}/users`, { method: "DELETE" })
            if (response.ok) {
                signOut()
            }
        } catch (error) {
            console.error("Failed to delete account", error)
        } finally {
            setDeleting(false)
            setConfirmingDelete(false)
        }
    }

    if (token && profile) {
        return (
            <div className="site-signin">
                <div className="site-signin-profile">
                    {profile.picture ? (
                        <img src={profile.picture} alt={profile.name} referrerPolicy="no-referrer" />
                    ) : (
                        // Apple shares no picture, so their initial stands in
                        <span className="site-signin-initial" aria-hidden="true">
                            {profile.name.charAt(0).toUpperCase()}
                        </span>
                    )}
                    <span className="site-signin-name">{profile.name}</span>
                </div>
                {!confirmingDelete ? (
                    <>
                        <button className="site-signin-out" onClick={signOut}>
                            Sign out
                        </button>
                        <button className="site-signin-delete-link" onClick={() => setConfirmingDelete(true)}>
                            Delete account
                        </button>
                    </>
                ) : (
                    <div className="site-signin-confirm">
                        <span>Delete your account?</span>
                        <button onClick={() => setConfirmingDelete(false)}>Cancel</button>
                        <button
                            className="site-signin-delete-confirm"
                            onClick={handleDeleteAccount}
                            disabled={deleting}
                        >
                            {deleting ? "Deleting..." : "Confirm"}
                        </button>
                    </div>
                )}
            </div>
        )
    }

    return (
        <div className="site-signin">
            {/* Google's own dark button on a dark page, where its white one
                stands out. Made afresh when the theme changes, as the button
                is drawn by Google once. */}
            <GoogleLogin
                key={dark ? "dark" : "light"}
                theme={dark ? "filled_black" : "outline"}
                onSuccess={(response: CredentialResponse) => {
                    if (!response.credential) {
                        return
                    }
                    setToken(response.credential)
                    void provisionUser()
                }}
                onError={() => console.error("Google sign-in failed")}
                useOneTap
            />
            <AppleSignIn />
        </div>
    )
}
